// Browser-only fixture host. No Core, database, ChatGPT or Codex connection.
import http from 'node:http';
import {readFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import snapshots from './card_visual_fixture.cjs';
const source=resolve(process.argv[2]||'internal/mcpserver/dev_bridge_ui.html'),before=process.argv[3];
const page=`<!doctype html><meta charset="utf-8"><title>Dev Bridge visual acceptance</title><style>body{font:13px system-ui;margin:24px;color:#333;background:#fafafa}nav{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:18px}label{display:grid;gap:4px}select{padding:6px}iframe{display:block;border:0;max-width:100%;background:transparent}#log{font-size:11px;color:#666}</style><nav><label>State<select id="state">${['INITIAL',...Object.keys(snapshots.states)].map(s=>'<option>'+s+'</option>').join('')}</select></label><label>Card width<select id="width"><option value="560">Normal · 560</option><option value="850">Wide · 850</option><option value="320">Narrow · 320</option></select></label><label>Names<select id="names"><option value="short">Normal names</option><option value="long">Long names</option></select></label><label>Theme<select id="theme"><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Asset<select id="asset"><option value="card">Production candidate</option><option value="before">Baseline</option></select></label><label>Structured plan<input id="structured-plan" type="checkbox" checked></label><label>Fail refresh<input id="fail-refresh" type="checkbox"></label></nav><iframe id="card" title="Production Dev Bridge Card"></iframe><p id="geometry" aria-label="Layout measurements"></p><p id="log">Isolated fixture · REAL_CHATGPT_HOST_NOT_RUN</p><script>
const states=${JSON.stringify(Object.keys(snapshots.states))},fixtures=${JSON.stringify(Object.fromEntries(Object.keys(snapshots.states).map(k=>[k,[snapshots.fixture(k),snapshots.fixture(k,true)]])))},branches=${JSON.stringify(snapshots.branches)};
const frame=document.getElementById('card'),state=document.getElementById('state'),width=document.getElementById('width'),names=document.getElementById('names'),asset=document.getElementById('asset'),theme=document.getElementById('theme');state.value='REVIEW_APPROVAL_REQUIRED';
function applyTheme(){if(frame.contentDocument?.documentElement)frame.contentDocument.documentElement.dataset.theme=theme.value;measure();}let layoutObserver;frame.addEventListener('load',()=>{layoutObserver?.disconnect();applyTheme();const root=frame.contentDocument?.getElementById('root');if(root){layoutObserver=new ResizeObserver(()=>{frame.style.height=(root.getBoundingClientRect().height+24)+'px';measure();});layoutObserver.observe(root);}});theme.onchange=applyTheme;
let currentPresentationId='';
function reportVisibility(){if(!currentPresentationId)return;const r=frame.getBoundingClientRect();const visibility=document.hidden?'HIDDEN':r.bottom>0&&r.top<innerHeight&&r.right>0&&r.left<innerWidth?'VISIBLE':'OFFSCREEN';frame.contentWindow.postMessage({jsonrpc:'2.0',method:'ui/notifications/dev-bridge-presentation-visibility',params:{presentationId:currentPresentationId,visibility}},location.origin);}
new IntersectionObserver(reportVisibility).observe(frame);addEventListener('scroll',reportVisibility);addEventListener('resize',reportVisibility);document.addEventListener('visibilitychange',reportVisibility);
function show(){currentPresentationId='';document.getElementById('geometry').textContent='';frame.style.width=width.value+'px';frame.style.height='900px';frame.src='/'+asset.value+'.html?state='+state.value+'&names='+names.value;}
state.onchange=names.onchange=asset.onchange=document.getElementById('structured-plan').onchange=show;width.onchange=()=>{frame.style.width=width.value+'px';measure()};
function measure(){const d=frame.contentDocument;if(!d||!d.querySelector('.card'))return;const titles=[...d.querySelectorAll('.current-value')].map(v=>Math.round(v.getBoundingClientRect().height/getComputedStyle(v).lineHeight.replace('px','')));document.getElementById('geometry').textContent=JSON.stringify({state:new URL(frame.contentWindow.location.href).searchParams.get('state'),theme:d.documentElement.dataset.theme,width:d.documentElement.clientWidth,scrollWidth:d.documentElement.scrollWidth,overflow:d.documentElement.scrollWidth>d.documentElement.clientWidth,titleLines:titles,taskSteps:d.querySelectorAll('.task-stages .step').length,productSteps:d.querySelectorAll('.db-task-primary > .stepper .step').length});}
addEventListener('message',event=>{if(event.source!==frame.contentWindow)return;const q=event.data;if(!q||q.jsonrpc!=='2.0')return;const reply=result=>frame.contentWindow.postMessage({jsonrpc:'2.0',id:q.id,result},location.origin);
if(q.method==='ui/initialize'){if(state.value==='INITIAL'){reply({});return;}frame.contentWindow.postMessage({jsonrpc:'2.0',method:'ui/notifications/tool-input',params:{arguments:{aiSessionId:'fixture-session',featureAreaId:'area-a',taskId:fixtures[state.value][0].selectedTaskId}}},location.origin);reply({hostCapabilities:{devBridgePresentation:{visibility:true,recall:true}}});}
else if(q.method==='ui/notifications/dev-bridge-presentation-subscribe'){currentPresentationId=q.params.presentationId;reportVisibility();}
else if(q.method==='ui/dev-bridge/recall-presentation'){if(q.params.presentationId!==currentPresentationId){reply({isError:true});return;}frame.scrollIntoView({block:'center'});reply({});reportVisibility();}
else if(q.method==='ui/notifications/size-changed'){frame.style.height=(q.params.height+12)+'px';measure();}
else if(q.method==='tools/call'){document.getElementById('log').textContent='REAL_CHATGPT_HOST_NOT_RUN · '+q.params.name;if(document.getElementById('fail-refresh').checked&&['dev_bridge_card_get','task_presentation_get','feature_area_presentation_get'].includes(q.params.name)){reply({isError:true});return;}if(q.params.name==='project_list')reply({structuredContent:{projects:[{projectId:'fixture',name:'Dev Bridge'}]}});else if(q.params.name==='dev_bridge_card_get'){if(document.getElementById('fail-refresh').checked){reply({isError:true});}else{const value=structuredClone(fixtures[state.value][names.value==='long'?1:0]);value.presentationId='workspace:fixture-session:project';value.featureAreas[0].runningDevelopmentTaskId=['IMPLEMENTATION_RUNNING','VERIFICATION_RUNNING'].includes(state.value)?'task-a':'';if(!document.getElementById('structured-plan').checked&&value.presentation?.taskView?.activity)delete value.presentation.taskView.activity.nativePlan;Object.assign(value.featureAreas[0],{availability:'AVAILABLE',reviewStatus:state.value==='REVIEW_RUNNING'?'RUNNING':'COMPLETE',commitStatus:'UNCOMMITTED'});reply({structuredContent:value});}}else if(q.params.name==='task_presentation_get')reply({structuredContent:fixtures[state.value][names.value==='long'?1:0].presentation});else if(q.params.name==='development_branch_list')reply({structuredContent:branches});else reply({isError:true,content:[{type:'text',text:'Fixture has no mutation backend.'}]});}});show();
</script>`;
const server=http.createServer(async(req,res)=>{try{const path=new URL(req.url,'http://localhost').pathname;res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Cache-Control','no-store');res.end(path==='/card.html'?(await readFile(source,'utf8')).replace('<script>', '<script>window.openai={widgetState:JSON.parse(sessionStorage.getItem("card-state")||"{}"),setWidgetState(value){this.widgetState=value;sessionStorage.setItem("card-state",JSON.stringify(value));}};</script><script>'):path==='/before.html'&&before?await readFile(before):page);}catch(e){res.writeHead(500);res.end(String(e));}});
server.listen(0,'127.0.0.1',()=>console.log('Visual fixture: http://127.0.0.1:'+server.address().port));
